export default [["q-fcps-pha4-01","The loading dose of a drug depends mainly on its:",["Volume of distribution","Clearance","Half-life","Bioavailability only"],"Loading dose equals the target concentration times the volume of distribution. Maintenance dose depends on clearance."],["q-fcps-pha4-02","Drug clearance determines the:",["Maintenance dose rate needed for a target steady-state concentration","Loading dose","Volume of distribution","Rate of absorption"],"At steady state the dosing rate equals clearance times the concentration."],["q-fcps-pha4-03","A partial agonist in the presence of a full agonist:",["Can reduce the overall response by competing for receptors","Always increases the response","Has no effect","Acts only on spare receptors"],"A partial agonist has lower intrinsic activity, so it displaces the full agonist and acts as a functional antagonist."],["q-fcps-pha4-04","A drug that gradually loses effect within minutes of repeated administration shows:",["Tachyphylaxis","Idiosyncrasy","Synergism","Hypersensitivity"],"Tachyphylaxis is rapid tolerance, for example to nasal decongestants and indirectly acting amines."],["q-fcps-pha4-05","Which of these is a CYP3A4 inhibitor that can raise statin levels and cause rhabdomyolysis?",["Clarithromycin","Rifampicin","Phenytoin","Carbamazepine"],"Macrolides such as clarithromycin and erythromycin, azole antifungals, grapefruit juice and ritonavir inhibit CYP3A4."],["q-fcps-pha4-06","Which of these is a potent enzyme inducer that can reduce the effectiveness of the oral contraceptive pill?",["St John's wort","Cimetidine","Ciprofloxacin","Fluconazole"],"St John's wort, rifampicin, phenytoin, carbamazepine and phenobarbital induce CYP enzymes."],["q-fcps-pha4-07","Slow acetylators are at increased risk of which adverse effect?",["Isoniazid neuropathy and drug-induced lupus","Warfarin resistance","Haemolysis","Malignant hyperthermia"],"N-acetyltransferase variants affect isoniazid, hydralazine and procainamide."],["q-fcps-pha4-08","A patient with poor CYP2D6 metabolism given codeine would have:",["Inadequate analgesia","Respiratory depression","Increased pain tolerance","Hepatotoxicity"],"Codeine is a prodrug converted to morphine by CYP2D6, so poor metabolisers gain little analgesia, and ultra-rapid metabolisers risk toxicity."],["q-fcps-pha4-09","Clopidogrel may be less effective in carriers of reduced-function alleles of:",["CYP2C19","CYP2D6","CYP3A4","CYP1A2"],"Clopidogrel needs CYP2C19 for activation."],["q-fcps-pha4-10","Which drug taken in the first trimester causes neural tube defects?",["Sodium valproate","Lithium","Warfarin","Tetracycline"],"Valproate carries a risk of spina bifida and lowers IQ. Warfarin causes a characteristic embryopathy with nasal hypoplasia, and lithium is linked to Ebstein anomaly."],["q-fcps-pha4-11","Thalidomide taken during pregnancy causes:",["Phocomelia","Neural tube defects","Teeth discolouration","Cleft palate only"],"Thalidomide interferes with limb development, and it is now used for myeloma and erythema nodosum leprosum under strict control."],["q-fcps-pha4-12","Fetal hydantoin syndrome is caused by:",["Phenytoin","Valproate","Lamotrigine","Levetiracetam"],"It includes craniofacial abnormalities, nail hypoplasia and growth deficiency."],["q-fcps-pha4-13","Isotretinoin is contraindicated in pregnancy because it causes:",["Craniofacial and cardiac malformations","Neonatal haemorrhage","Grey baby syndrome","Ototoxicity"],"Retinoids are potent teratogens, and pregnancy must be excluded before and during therapy."],["q-fcps-pha4-14","Which drug is used to treat glaucoma by causing miosis and contraction of the ciliary muscle?",["Pilocarpine","Atropine","Timolol","Phenylephrine"],"Pilocarpine opens the trabecular meshwork and increases aqueous outflow."],["q-fcps-pha4-15","Pralidoxime in organophosphate poisoning acts by:",["Reactivating acetylcholinesterase before ageing occurs","Blocking muscarinic receptors","Inhibiting nicotinic receptors","Chelating the poison"],"Pralidoxime regenerates the enzyme and should be given early, and atropine treats the muscarinic effects."],["q-fcps-pha4-16","Physostigmine is useful in anticholinergic poisoning because it:",["Crosses the blood-brain barrier and inhibits acetylcholinesterase","Blocks muscarinic receptors","Releases noradrenaline","Activates nicotinic channels directly"],"It is a tertiary amine and so reverses both central and peripheral antimuscarinic toxicity."],["q-fcps-pha4-17","Phenylephrine is a:",["Selective alpha-1 agonist","Beta-2 agonist","Alpha-2 antagonist","Dopamine agonist"],"It raises blood pressure by vasoconstriction, causing reflex bradycardia, and is used as a nasal decongestant and mydriatic."],["q-fcps-pha4-18","Isoprenaline acts on which receptors?",["Beta-1 and beta-2","Alpha-1 only","Alpha-2 only","Dopamine D1"],"It increases heart rate and contractility and causes vasodilatation, so diastolic pressure falls."],["q-fcps-pha4-19","At low doses (1 to 3 micrograms per kg per minute), dopamine acts mainly on:",["Dopamine D1 receptors causing renal vasodilatation","Beta-1 receptors","Alpha-1 receptors","Beta-2 receptors"],"Higher doses stimulate beta-1 receptors and very high doses stimulate alpha-1 receptors."],["q-fcps-pha4-20","Which beta-blocker has intrinsic sympathomimetic activity?",["Pindolol","Propranolol","Atenolol","Metoprolol"],"Pindolol and acebutolol are partial agonists, which gives less bradycardia."],["q-fcps-pha4-21","Which drug is a combined alpha and beta blocker used in heart failure and hypertension?",["Carvedilol","Atenolol","Prazosin","Bisoprolol"],"Carvedilol blocks beta-1, beta-2 and alpha-1 receptors and improves survival in heart failure."],["q-fcps-pha4-22","Nitrates relieve angina mainly by:",["Venodilatation that reduces preload","Increasing heart rate","Blocking calcium channels","Increasing contractility"],"Nitric oxide release raises cGMP and relaxes smooth muscle, so venous return and myocardial oxygen demand fall."],["q-fcps-pha4-23","Which is a common adverse effect of nifedipine?",["Reflex tachycardia and ankle oedema","Bradycardia","Constipation","AV block"],"Dihydropyridines are vascular selective and cause flushing, headache and peripheral oedema. Verapamil causes constipation."],["q-fcps-pha4-24","Hydralazine is associated with:",["Drug-induced lupus","Hyperkalaemia","Cough","Gout"],"Slow acetylators are at higher risk of lupus-like syndrome with antihistone antibodies."],["q-fcps-pha4-25","ACE inhibitors are contraindicated in:",["Bilateral renal artery stenosis","Heart failure","Diabetic nephropathy","Post-myocardial infarction"],"Loss of angiotensin II-mediated efferent constriction in a stenosed kidney can cause acute renal failure."],["q-fcps-pha4-26","Which class of antiarrhythmic is lidocaine?",["Class IB","Class IA","Class IC","Class III"],"Lidocaine blocks sodium channels in ischaemic or depolarised tissue and shortens the action potential."],["q-fcps-pha4-27","Flecainide is contraindicated after myocardial infarction because it:",["Increases mortality (proarrhythmic) in the CAST trial","Causes heart block only","Prolongs QT","Causes pulmonary fibrosis"],"Class IC drugs are pro-arrhythmic in structural heart disease."],["q-fcps-pha4-28","Which antiarrhythmic prolongs the QT interval and can cause torsades de pointes?",["Sotalol","Lidocaine","Verapamil","Adenosine"],"Sotalol is a class III agent with beta-blocking properties. Other QT-prolonging drugs include macrolides and many antipsychotics."],["q-fcps-pha4-29","The treatment of torsades de pointes is:",["Intravenous magnesium sulphate","Amiodarone","Digoxin","Procainamide"],"Magnesium stabilises the membrane, and the offending drug is stopped and potassium corrected."],["q-fcps-pha4-30","Which drug improves survival in heart failure with reduced ejection fraction by blocking aldosterone receptors?",["Spironolactone","Furosemide","Digoxin","Amlodipine"],"Spironolactone and eplerenone reduce mortality, but monitor for hyperkalaemia and gynaecomastia."],["q-fcps-pha4-31","Ivabradine reduces heart rate by inhibiting:",["The funny current (If) in the sinoatrial node","L-type calcium channels","Beta-1 receptors","The sodium-potassium pump"],"It lowers rate without negative inotropy and can cause visual phosphenes."],["q-fcps-pha4-32","Statin-induced myopathy is more likely when the statin is combined with:",["Fibrates","Ezetimibe","Aspirin","Metformin"],"Gemfibrozil raises statin levels by inhibiting glucuronidation, and the risk of rhabdomyolysis increases."],["q-fcps-pha4-33","Ezetimibe lowers cholesterol by:",["Inhibiting NPC1L1-mediated intestinal cholesterol absorption","Inhibiting HMG-CoA reductase","Binding bile acids","Activating PPAR-alpha"],"It reduces cholesterol absorption and is added when statins alone are insufficient."],["q-fcps-pha4-34","Which lipid-lowering drug causes flushing mediated by prostaglandins?",["Nicotinic acid (niacin)","Cholestyramine","Fenofibrate","Atorvastatin"],"Aspirin taken before the dose reduces flushing."],["q-fcps-pha4-35","Reversal of warfarin in a patient with life-threatening bleeding requires:",["Vitamin K and prothrombin complex concentrate","Protamine sulphate","Tranexamic acid alone","Idarucizumab"],"Vitamin K restores synthesis, but its effect takes hours, so PCC gives immediate reversal."],["q-fcps-pha4-36","Idarucizumab reverses the effect of:",["Dabigatran","Rivaroxaban","Heparin","Warfarin"],"It is a monoclonal antibody fragment that binds dabigatran. Andexanet alfa reverses factor Xa inhibitors."],["q-fcps-pha4-37","Protamine sulphate neutralises:",["Heparin","Warfarin","Alteplase","Clopidogrel"],"The positively charged protein binds negatively charged heparin."],["q-fcps-pha4-38","Alteplase is:",["A recombinant tissue plasminogen activator","A factor Xa inhibitor","A glycoprotein IIb/IIIa blocker","A vitamin K antagonist"],"It converts plasminogen to plasmin and is used within the time window in ischaemic stroke and myocardial infarction."],["q-fcps-pha4-39","Tranexamic acid acts by:",["Inhibiting plasminogen activation","Activating factor VII","Inhibiting thrombin","Blocking P2Y12"],"It is a lysine analogue that blocks fibrin binding of plasminogen and is used for menorrhagia and trauma."],["q-fcps-pha4-40","Loop diuretics commonly cause:",["Hypokalaemia and ototoxicity","Hyperkalaemia","Hypercalcaemia","Hypouricaemia"],"Furosemide wastes potassium and magnesium and can cause hyperuricaemia and, at high doses, ototoxicity. It increases calcium excretion."],["q-fcps-pha4-41","Thiazide diuretics:",["Reduce urinary calcium excretion","Increase calcium excretion","Cause hyperkalaemia","Are effective at a GFR below 10"],"They are used in idiopathic hypercalciuria with stones and can cause hypercalcaemia, hyponatraemia and hyperglycaemia."],["q-fcps-pha4-42","Amiloride is a diuretic that acts by blocking:",["ENaC in the collecting duct","Na-K-2Cl cotransporter","Aldosterone receptor","Carbonic anhydrase"],"It is potassium-sparing, and lithium-induced nephrogenic diabetes insipidus is treated with it."],["q-fcps-pha4-43","Salmeterol is best described as a:",["Long-acting beta-2 agonist","Short-acting beta-2 agonist","Muscarinic antagonist","Leukotriene antagonist"],"It is used with inhaled corticosteroids for asthma and should not be used alone."],["q-fcps-pha4-44","Montelukast acts by:",["Blocking cysteinyl leukotriene receptors","Inhibiting 5-lipoxygenase","Stabilising mast cells","Inhibiting phosphodiesterase"],"Zileuton inhibits 5-lipoxygenase. Montelukast is useful in aspirin-sensitive asthma and exercise-induced bronchoconstriction."],["q-fcps-pha4-45","Which adverse effect is common with high-dose inhaled corticosteroids?",["Oral candidiasis and hoarseness","Adrenal crisis","Bronchospasm only","Osteoporosis at standard doses"],"Rinsing the mouth and using a spacer reduces local effects."],["q-fcps-pha4-46","Theophylline toxicity can present with:",["Seizures and tachyarrhythmias","Bradycardia","Drowsiness only","Hypokalaemia with constipation only"],"It has a narrow therapeutic index, and its clearance falls with ciprofloxacin, erythromycin, heart failure and cirrhosis."],["q-fcps-pha4-47","Which drug acts as a prostaglandin E1 analogue and protects the gastric mucosa but is contraindicated in pregnancy?",["Misoprostol","Sucralfate","Omeprazole","Ranitidine"],"Misoprostol causes uterine contraction, and its main adverse effect is diarrhoea."],["q-fcps-pha4-48","Sucralfate acts by:",["Forming a protective barrier over the ulcer base in an acid environment","Blocking H2 receptors","Inhibiting the proton pump","Neutralising acid"],"It requires an acidic pH for activation, so it should not be given with antacids, and it may cause constipation."],["q-fcps-pha4-49","Domperidone is preferred to metoclopramide in Parkinson disease because it:",["Does not cross the blood-brain barrier","Is a dopamine agonist","Blocks 5-HT3 receptors","Has no QT effect"],"It is a peripheral D2 antagonist, but it can still prolong the QT interval."],["q-fcps-pha4-50","Loperamide acts by:",["Stimulating mu opioid receptors in the gut to reduce motility","Blocking 5-HT3 receptors","Binding bile acids","Increasing intestinal secretion"],"It has poor central penetration because it is a P-glycoprotein substrate, so it has little abuse potential at normal doses."],["q-fcps-pha4-51","A patient on metformin has a CT with intravenous contrast. Why is metformin withheld?",["Risk of lactic acidosis with acute kidney injury","Risk of hypoglycaemia","Contrast inactivates metformin","Risk of hepatotoxicity"],"Metformin is renally cleared and accumulates if the kidneys are injured."],["q-fcps-pha4-52","SGLT2 inhibitors such as empagliflozin commonly cause:",["Genital mycotic infections and euglycaemic ketoacidosis","Hypoglycaemia in monotherapy","Weight gain","Pancreatitis"],"They cause glycosuria, with benefits for heart failure and chronic kidney disease."],["q-fcps-pha4-53","GLP-1 receptor agonists such as liraglutide cause:",["Weight loss and nausea","Weight gain","Hypoglycaemia as monotherapy","Lactic acidosis"],"They increase glucose-dependent insulin secretion and delay gastric emptying."],["q-fcps-pha4-54","Carbimazole is associated with:",["Agranulocytosis","Hypercalcaemia","Pulmonary fibrosis","Optic neuritis"],"Patients should report sore throat and fever, and propylthiouracil causes hepatotoxicity."],["q-fcps-pha4-55","Desmopressin is used in all EXCEPT:",["SIADH","Central diabetes insipidus","Nocturnal enuresis","Mild haemophilia A"],"It is an ADH analogue, so it would worsen SIADH and cause hyponatraemia."],["q-fcps-pha4-56","Octreotide is a synthetic analogue of:",["Somatostatin","Growth hormone","Vasopressin","Oxytocin"],"It is used in acromegaly, carcinoid syndrome and variceal bleeding."],["q-fcps-pha4-57","Third-generation cephalosporins have:",["Better gram-negative activity and CNS penetration","Better gram-positive activity than first generation","Anaerobic activity","Activity against MRSA"],"Ceftriaxone is used for meningitis and gonorrhoea, but cephalosporins have no activity against enterococci or Listeria."],["q-fcps-pha4-58","Ceftriaxone should be avoided in neonates because it:",["Displaces bilirubin and may precipitate with calcium","Causes grey baby syndrome","Causes tendon rupture","Is nephrotoxic"],"It can cause kernicterus and lethal calcium-ceftriaxone precipitates."],["q-fcps-pha4-59","Which beta-lactam has no cross-reactivity with penicillin allergy and covers gram-negative rods only?",["Aztreonam","Imipenem","Cefazolin","Piperacillin"],"Aztreonam is a monobactam active against aerobic gram-negative bacteria, including Pseudomonas."],["q-fcps-pha4-60","Imipenem is given with cilastatin in order to:",["Inhibit renal dehydropeptidase","Increase absorption","Reduce resistance","Block penicillin-binding proteins"],"Cilastatin prevents renal breakdown, and imipenem lowers the seizure threshold."],["q-fcps-pha4-61","Which antibiotic prolongs the QT interval and is a potent CYP3A4 inhibitor?",["Clarithromycin","Azithromycin","Doxycycline","Amoxicillin"],"Clarithromycin and erythromycin inhibit CYP3A4 and prolong the QT interval, but azithromycin has fewer interactions."],["q-fcps-pha4-62","Clindamycin is most strongly associated with:",["Pseudomembranous colitis","Ototoxicity","Tendon rupture","Red man syndrome"],"Broad disruption of gut flora allows Clostridioides difficile overgrowth."],["q-fcps-pha4-63","Linezolid acts by:",["Inhibiting formation of the 50S initiation complex","Blocking the 30S subunit","Inhibiting cell wall synthesis","Inhibiting DNA gyrase"],"It is active against MRSA and VRE and causes myelosuppression and, with SSRIs, serotonin syndrome."],["q-fcps-pha4-64","Pyrazinamide commonly causes:",["Hyperuricaemia","Optic neuritis","Peripheral neuropathy","Orange urine"],"It inhibits renal urate excretion, and it is hepatotoxic."],["q-fcps-pha4-65","Fluconazole is the drug of choice for:",["Cryptococcal meningitis maintenance and candidiasis","Invasive aspergillosis","Mucormycosis","Dermatophyte nail infection"],"Fluconazole penetrates the CSF well, but it has no activity against moulds."],["q-fcps-pha4-66","The first-line treatment of invasive aspergillosis is:",["Voriconazole","Fluconazole","Nystatin","Terbinafine"],"Voriconazole can cause visual disturbance and hepatotoxicity, and amphotericin B is an alternative."],["q-fcps-pha4-67","Oseltamivir acts by inhibiting:",["Neuraminidase","DNA polymerase","Reverse transcriptase","Protease"],"It prevents viral release and works best when started within 48 hours of symptoms."],["q-fcps-pha4-68","Zidovudine commonly causes:",["Bone marrow suppression with macrocytic anaemia","Pancreatitis","Nephrolithiasis","Hepatic steatosis only"],"It is a nucleoside reverse transcriptase inhibitor, and it is used to prevent mother-to-child transmission."],["q-fcps-pha4-69","Indinavir can cause:",["Nephrolithiasis","Anaemia","Pancreatitis","Peripheral neuropathy"],"Hydration reduces the risk, and protease inhibitors cause lipodystrophy and CYP3A4 inhibition."],["q-fcps-pha4-70","Chloroquine in long-term use can cause:",["Retinopathy","Haemolysis in G6PD deficiency","Hepatitis","Hypoglycaemia only"],"Hydroxychloroquine and chloroquine can cause bull's eye maculopathy and need screening."],["q-fcps-pha4-71","Artesunate is the drug of choice for:",["Severe falciparum malaria","Vivax radical cure","Amoebic liver abscess","Leishmaniasis"],"Intravenous artesunate has better survival than quinine."],["q-fcps-pha4-72","Praziquantel is used for:",["Schistosomiasis and tapeworms","Ascariasis only","Strongyloides only","Amoebiasis"],"It increases calcium influx into the parasite, causing paralysis."],["q-fcps-pha4-73","Ivermectin is the drug of choice for:",["Strongyloidiasis and onchocerciasis","Hydatid disease","Taeniasis","Giardiasis"],"It acts on glutamate-gated chloride channels of nematodes."],["q-fcps-pha4-74","Vincristine characteristically causes:",["Peripheral neuropathy","Myelosuppression as the dose-limiting effect","Cardiotoxicity","Haemorrhagic cystitis"],"It inhibits microtubule polymerisation, and vinblastine causes myelosuppression."],["q-fcps-pha4-75","Cisplatin is associated with:",["Nephrotoxicity, ototoxicity and severe emesis","Pulmonary fibrosis","Cardiomyopathy","Peripheral neuropathy from taxane action"],"Amifostine and hydration reduce renal toxicity."],["q-fcps-pha4-76","Paclitaxel acts by:",["Stabilising microtubules","Inhibiting topoisomerase","Alkylating DNA","Inhibiting dihydrofolate reductase"],"It prevents microtubule depolymerisation, so mitosis is arrested."],["q-fcps-pha4-77","Imatinib is used for:",["Chronic myeloid leukaemia (BCR-ABL tyrosine kinase)","Hairy cell leukaemia","Hodgkin lymphoma","Multiple myeloma"],"It also treats gastrointestinal stromal tumours through KIT inhibition."],["q-fcps-pha4-78","Tamoxifen increases the risk of:",["Endometrial carcinoma","Osteoporosis in postmenopausal women","Breast cancer in the opposite breast","Ovarian cancer"],"It is an oestrogen receptor antagonist in the breast but a partial agonist in the endometrium and bone."],["q-fcps-pha4-79","Tacrolimus acts by:",["Binding FKBP and inhibiting calcineurin","Inhibiting inosine monophosphate dehydrogenase","Inhibiting mTOR","Blocking the IL-2 receptor"],"Its adverse effects include nephrotoxicity, neurotoxicity and diabetes, and mycophenolate inhibits IMPDH."],["q-fcps-pha4-80","Indomethacin is used to close a patent ductus arteriosus because it:",["Inhibits prostaglandin synthesis","Constricts the ductus directly via thromboxane","Blocks calcium channels","Increases oxygen tension"],"Prostaglandin E2 keeps the ductus open, and alprostadil is used to keep it open in duct-dependent defects."],["q-fcps-pha4-81","Celecoxib, compared with non-selective NSAIDs, has:",["Less gastric toxicity but an increased cardiovascular risk","More gastric ulceration","No renal effects","Antiplatelet action"],"COX-2 selectivity spares gastric COX-1 but reduces prostacyclin without reducing thromboxane."],["q-fcps-pha4-82","Colchicine acts in acute gout by:",["Inhibiting microtubule polymerisation and neutrophil migration","Inhibiting xanthine oxidase","Increasing uric acid excretion","Inhibiting COX"],"It commonly causes diarrhoea, and toxicity includes bone marrow suppression."],["q-fcps-pha4-83","Probenecid raises plasma levels of penicillin because it:",["Inhibits renal tubular secretion of organic acids","Inhibits hepatic metabolism","Increases absorption","Binds albumin"],"It is also a uricosuric drug that increases uric acid excretion."],["q-fcps-pha4-84","Hydroxychloroquine and methotrexate are examples of:",["Disease-modifying antirheumatic drugs","NSAIDs","Biologic TNF inhibitors","Corticosteroids"],"DMARDs slow the progression of rheumatoid arthritis, and methotrexate is the anchor drug."],["q-fcps-pha4-85","Before starting infliximab, a patient should be screened for:",["Latent tuberculosis","Glucose-6-phosphate dehydrogenase deficiency","HLA-B27","Thiopurine methyltransferase"],"TNF-alpha is needed to maintain granulomas, so reactivation of tuberculosis is a risk."],["q-fcps-pha4-86","Phenytoin shows zero-order kinetics at higher doses, so:",["A small dose increase can cause a large rise in plasma concentration","The half-life is constant","Dosing is independent of level","Clearance increases"],"Metabolic enzymes become saturated, and toxicity includes nystagmus, ataxia and diplopia."],["q-fcps-pha4-87","Ethosuximide is the first-line drug for:",["Absence seizures","Tonic-clonic seizures","Status epilepticus","Myoclonic seizures"],"It blocks T-type calcium channels in thalamic neurons."],["q-fcps-pha4-88","Lamotrigine requires slow dose titration because of the risk of:",["Stevens-Johnson syndrome","Hepatic failure","Gingival hyperplasia","Pancreatitis"],"The risk of rash is higher with rapid titration and with concurrent valproate."],["q-fcps-pha4-89","Carbamazepine commonly causes:",["Hyponatraemia and enzyme induction","Gingival hyperplasia","Weight gain and tremor","Hirsutism"],"SIADH-like effects are seen, and HLA-B*1502 predisposes to Stevens-Johnson syndrome in some Asian populations."],["q-fcps-pha4-90","Neuroleptic malignant syndrome is treated with:",["Dantrolene and supportive care","Haloperidol","Atropine","Naloxone"],"It presents with hyperthermia, muscle rigidity and autonomic instability, and the antipsychotic is stopped."],["q-fcps-pha4-91","Which antipsychotic is most likely to cause weight gain and metabolic syndrome?",["Olanzapine","Haloperidol","Aripiprazole","Ziprasidone"],"Atypical antipsychotics, especially olanzapine and clozapine, cause weight gain and dyslipidaemia."],["q-fcps-pha4-92","Bupropion is contraindicated in patients with:",["Seizure disorders and bulimia","Smoking","Depression","Obesity"],"It lowers the seizure threshold and is also used for smoking cessation."],["q-fcps-pha4-93","Levodopa is given with carbidopa in order to:",["Inhibit peripheral dopa decarboxylase","Inhibit MAO-B in the brain","Block dopamine receptors","Increase dopamine release"],"Carbidopa does not cross the blood-brain barrier, so more levodopa reaches the brain and nausea is reduced."],["q-fcps-pha4-94","Sumatriptan is contraindicated in:",["Ischaemic heart disease","Asthma","Epilepsy","Peptic ulcer"],"5-HT1B/1D agonists cause coronary vasoconstriction."],["q-fcps-pha4-95","Halothane can cause:",["Fulminant hepatitis","Pulmonary fibrosis","Optic neuritis","Ototoxicity"],"Repeated exposure may cause immune-mediated hepatic necrosis."],["q-fcps-pha4-96","Prolonged nitrous oxide anaesthesia can cause:",["Megaloblastic anaemia by inactivating vitamin B12","Hepatitis","Nephrotoxicity","Malignant hyperthermia"],"It oxidises the cobalt of cobalamin and inhibits methionine synthase."],["q-fcps-pha4-97","Propofol is characterised by:",["Rapid recovery and antiemetic effect","Prolonged recovery with accumulation","Strong analgesia","Adrenocortical suppression"],"It is used for induction and sedation, and its adverse effects are hypotension and injection pain."],["q-fcps-pha4-98","Digoxin-specific antibody fragments (Fab) are used for:",["Life-threatening digoxin toxicity","Warfarin reversal","Heparin overdose","Beta-blocker poisoning"],"They bind digoxin and are given for dangerous arrhythmias or hyperkalaemia."],["q-fcps-pha4-99","Dimercaprol is used as a chelator in poisoning with:",["Arsenic, mercury and lead","Iron","Copper only","Cyanide"],"It is a dithiol chelator given by deep intramuscular injection, and succimer is an oral alternative."],["q-fcps-pha4-100","Activated charcoal is NOT effective for poisoning with:",["Lithium","Paracetamol","Tricyclic antidepressants","Aspirin"],"Charcoal adsorbs most drugs, but it binds poorly to small ionised compounds such as lithium, iron, alcohols and corrosives."]];
